w('guides/index.html',page({url:'/guides/',title:'Kegel Guides for Men: Plain-English Answers | Kegzo',desc:'Short, plain-English guides to kegel exercises for men: technique, timelines, mistakes, reverse kegels and what the research says.',crumb:[['Home','/'],['Guides','/guides/']],
 body:`<h1>Kegel guides for men</h1><p class="lead answer">Plain-English answers to the questions men ask most about kegel exercises: how to find the right muscle, how long training takes, the common mistakes, reverse kegels and the positions to train in.</p><section id="how"><h2>How Kegzo works</h2><ol class="how3"><li><span class="hn">1</span><div><b>Get your plan</b><p>Answer 9 quick taps about your goal, your time and how things feel. Kegzo builds your 28-day path.</p></div></li><li><span class="hn">2</span><div><b>Press Start once a day</b><p>Follow the coach's voice and the video. He counts every squeeze, hold and release for you.</p></div></li><li><span class="hn">3</span><div><b>Level up</b><p>Earn XP, keep your streak, unlock badges and watch your progress grow on your dashboard.</p></div></li></ol><p><a class="btn hot" href="/app.html">Start training free</a></p></section><h2>All guides</h2><div class="links">${GUIDES.map(g=>`<a class="lk" href="/guides/${g.slug}.html"><span>${esc(g.h1)}<small>${esc(g.desc)}</small></span></a>`).join('')}</div>${cta()}`}));pages.push(['/guides/','0.9']);

